import type {TrackerSelectGroup} from '../../../components/TrackerSelect/types';

/**
 * Returns a tag-prefixed group id when the group has a tag, otherwise returns the group id as-is.
 */
export function getGroupId(group: TrackerSelectGroup): string {
    const tag = group.tag;

    return tag ? `${tag}-${group.id}` : group.id;
}
